import{b as r,O as d,g as o,j as e}from"./chunks/framework.DcaUmd3X.js";const b=JSON.parse('{"title":"JMeter 功能速查","description":"","frontmatter":{},"headers":[],"relativePath":"performance/jmeter/reference/index.md","filePath":"性能测试/1.Jmeter/09.JMeter功能速查.md","lastUpdated":1781755252000}'),n={name:"performance/jmeter/reference/index.md"};function s(a,t,g,h,l,i){return d(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="jmeter-功能速查" tabindex="-1">JMeter 功能速查 <a class="header-anchor" href="#jmeter-功能速查" aria-label="Permalink to &quot;JMeter 功能速查&quot;">​</a></h1><blockquote><p>按 JMeter 右键菜单的结构，列出所有功能及其一句话说明。忘了某个元件干什么用，来这翻。</p></blockquote><h2 id="线程-用户-—-threads" tabindex="-1">线程（用户）— Threads <a class="header-anchor" href="#线程-用户-—-threads" aria-label="Permalink to &quot;线程（用户）— Threads&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>线程组 (Thread Group)</strong></td><td>标准用户模型：设多少人、怎么启动、跑几轮</td></tr><tr><td><strong>setUp 线程组 (setUp Thread Group)</strong></td><td>最先执行，做登录、准备数据</td></tr><tr><td><strong>tearDown 线程组 (tearDown Thread Group)</strong></td><td>最后执行，做清理、登出</td></tr></tbody></table><h3 id="插件线程组-需装-custom-thread-groups" tabindex="-1">插件线程组（需装 Custom Thread Groups） <a class="header-anchor" href="#插件线程组-需装-custom-thread-groups" aria-label="Permalink to &quot;插件线程组（需装 Custom Thread Groups）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>Concurrency Thread Group</strong></td><td>阶梯式加压，找性能拐点</td></tr><tr><td><strong>Ultimate Thread Group</strong></td><td>多波次浪涌，模拟突发流量</td></tr><tr><td><strong>Arrivals Thread Group</strong></td><td>控制每秒请求数（TPS）</td></tr><tr><td><strong>Free-Form Arrivals Thread Group</strong></td><td>灵活控制请求速率起止值</td></tr></tbody></table><h2 id="取样器-—-sampler" tabindex="-1">取样器 — Sampler <a class="header-anchor" href="#取样器-—-sampler" aria-label="Permalink to &quot;取样器 — Sampler&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>HTTP 请求 (HTTP Request)</strong></td><td>发 HTTP/HTTPS 请求，90% 场景用这个</td></tr><tr><td><strong>JDBC 请求 (JDBC Request)</strong></td><td>执行 SQL，测数据库</td></tr><tr><td><strong>JSR223 取样器 (JSR223 Sampler)</strong></td><td>写 Groovy 脚本自定义请求</td></tr><tr><td><strong>TCP 取样器 (TCP Sampler)</strong></td><td>测自定义 TCP 协议</td></tr><tr><td><strong>FTP 请求 (FTP Request)</strong></td><td>测文件上传下载</td></tr><tr><td><strong>JMS Publisher / Subscriber / Point-to-Point</strong></td><td>测消息队列（ActiveMQ 等）</td></tr><tr><td><strong>SMTP 取样器 (SMTP Sampler)</strong></td><td>测邮件发送</td></tr><tr><td><strong>OS 进程取样器 (OS Process Sampler)</strong></td><td>调用系统命令</td></tr><tr><td><strong>Java 请求 (Java Request)</strong></td><td>执行自定义 Java 类</td></tr><tr><td><strong>LDAP 请求 (LDAP Request)</strong></td><td>测目录服务</td></tr><tr><td><strong>调试取样器 (Debug Sampler)</strong></td><td>查看当前变量值，调试用</td></tr><tr><td><strong>测试活动 (Test Action)</strong></td><td>插入暂停或循环断点</td></tr></tbody></table><h3 id="插件取样器" tabindex="-1">插件取样器 <a class="header-anchor" href="#插件取样器" aria-label="Permalink to &quot;插件取样器&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>WebSocket Sampler</strong></td><td>测 WebSocket 实时通信</td></tr><tr><td><strong>GraphQL HTTP Request</strong></td><td>测 GraphQL 接口</td></tr></tbody></table><h2 id="逻辑控制器-—-logic-controller" tabindex="-1">逻辑控制器 — Logic Controller <a class="header-anchor" href="#逻辑控制器-—-logic-controller" aria-label="Permalink to &quot;逻辑控制器 — Logic Controller&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>简单控制器 (Simple Controller)</strong></td><td>纯分组容器，无逻辑</td></tr><tr><td><strong>If 控制器 (If Controller)</strong></td><td>条件成立才执行子节点</td></tr><tr><td><strong>While 控制器 (While Controller)</strong></td><td>循环直到条件为 false</td></tr><tr><td><strong>ForEach 控制器 (ForEach Controller)</strong></td><td>遍历一组变量</td></tr><tr><td><strong>事务控制器 (Transaction Controller)</strong></td><td>多个请求打包为一个事务计时</td></tr><tr><td><strong>吞吐量控制器 (Throughput Controller)</strong></td><td>按次数或百分比分配执行</td></tr><tr><td><strong>交替控制器 (Interleave Controller)</strong></td><td>子节点轮流执行，每次跑一个</td></tr><tr><td><strong>随机控制器 (Random Controller)</strong></td><td>随机选一个子节点执行</td></tr><tr><td><strong>仅一次控制器 (Once Only Controller)</strong></td><td>子节点只跑一次，后面循环跳过</td></tr><tr><td><strong>模块控制器 (Module Controller)</strong></td><td>引用同计划内的另一个控制器</td></tr><tr><td><strong>包含控制器 (Include Controller)</strong></td><td>导入外部 .jmx 文件</td></tr><tr><td><strong>录制控制器 (Recording Controller)</strong></td><td>配合代理录制时存储请求</td></tr><tr><td><strong>循环控制器 (Loop Controller)</strong></td><td>子节点循环执行指定次数</td></tr><tr><td><strong>Switch 控制器 (Switch Controller)</strong></td><td>按名称或索引选一个子节点执行</td></tr><tr><td><strong>运行时控制器 (Runtime Controller)</strong></td><td>控制子节点运行多长时间</td></tr></tbody></table><h2 id="配置元件-—-config-element" tabindex="-1">配置元件 — Config Element <a class="header-anchor" href="#配置元件-—-config-element" aria-label="Permalink to &quot;配置元件 — Config Element&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>HTTP 请求默认值 (HTTP Request Defaults)</strong></td><td>统一设协议、服务器、端口</td></tr><tr><td><strong>HTTP 信息头管理器 (HTTP Header Manager)</strong></td><td>统一管理请求头</td></tr><tr><td><strong>HTTP Cookie 管理器 (HTTP Cookie Manager)</strong></td><td>自动存取 Cookie，每个线程独立</td></tr><tr><td><strong>HTTP 缓存管理器 (HTTP Cache Manager)</strong></td><td>模拟浏览器缓存行为</td></tr><tr><td><strong>CSV 数据文件设置 (CSV Data Set Config)</strong></td><td>从 CSV 文件读测试数据</td></tr><tr><td><strong>用户定义的变量 (User Defined Variables)</strong></td><td>定义全局静态变量</td></tr><tr><td><strong>计数器 (Counter)</strong></td><td>生成自增序号</td></tr><tr><td><strong>随机变量 (Random Variable)</strong></td><td>生成随机值</td></tr><tr><td><strong>JDBC 连接配置 (JDBC Connection Configuration)</strong></td><td>配置数据库连接池</td></tr><tr><td><strong>DNS 缓存管理器 (DNS Cache Manager)</strong></td><td>自定义 DNS 解析</td></tr><tr><td><strong>FTP 请求默认值 (FTP Request Defaults)</strong></td><td>FTP 请求的公共配置</td></tr><tr><td><strong>Keystore 配置 (Keystore Configuration)</strong></td><td>配置 SSL 证书</td></tr><tr><td><strong>登录配置元件 (Login Config Element)</strong></td><td>管理用户名密码认证</td></tr></tbody></table><h2 id="定时器-—-timer" tabindex="-1">定时器 — Timer <a class="header-anchor" href="#定时器-—-timer" aria-label="Permalink to &quot;定时器 — Timer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>固定定时器 (Constant Timer)</strong></td><td>每次停顿固定时长</td></tr><tr><td><strong>均匀随机定时器 (Uniform Random Timer)</strong></td><td>在范围内随机停顿，最常用</td></tr><tr><td><strong>高斯随机定时器 (Gaussian Random Timer)</strong></td><td>正态分布随机停顿</td></tr><tr><td><strong>泊松随机定时器 (Poisson Random Timer)</strong></td><td>泊松分布随机停顿</td></tr><tr><td><strong>同步定时器 (Synchronizing Timer)</strong></td><td>集合点：等人凑够一起冲</td></tr><tr><td><strong>常数吞吐量定时器 (Constant Throughput Timer)</strong></td><td>控制每秒发多少请求</td></tr><tr><td><strong>精准吞吐量定时器 (Precise Throughput Timer)</strong></td><td>更精准的吞吐量控制</td></tr><tr><td><strong>BeanShell 定时器 (BeanShell Timer)</strong></td><td>脚本自定义停顿逻辑（已过时）</td></tr><tr><td><strong>JSR223 定时器 (JSR223 Timer)</strong></td><td>Groovy 脚本自定义停顿，推荐</td></tr></tbody></table><h2 id="前置处理器-—-pre-processor" tabindex="-1">前置处理器 — Pre-Processor <a class="header-anchor" href="#前置处理器-—-pre-processor" aria-label="Permalink to &quot;前置处理器 — Pre-Processor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>用户参数 (User Parameters)</strong></td><td>为每个线程设置独立参数</td></tr><tr><td><strong>HTML 链接解析器 (HTML Link Parser)</strong></td><td>从 HTML 页面提取链接供后续请求</td></tr><tr><td><strong>HTTP URL 重写修饰符 (HTTP URL Re-writing Modifier)</strong></td><td>自动追加 session ID 到 URL</td></tr><tr><td><strong>BeanShell 前置处理器 (BeanShell PreProcessor)</strong></td><td>脚本自定义前置逻辑（已过时）</td></tr><tr><td><strong>JSR223 前置处理器 (JSR223 PreProcessor)</strong></td><td>Groovy 脚本自定义前置逻辑，推荐</td></tr><tr><td><strong>JDBC 前置处理器 (JDBC PreProcessor)</strong></td><td>取样器前执行 SQL</td></tr><tr><td><strong>取样器超时 (Sample Timeout)</strong></td><td>设定取样器的超时时间</td></tr></tbody></table><h2 id="后置处理器-—-post-processor" tabindex="-1">后置处理器 — Post-Processor <a class="header-anchor" href="#后置处理器-—-post-processor" aria-label="Permalink to &quot;后置处理器 — Post-Processor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>JSON 提取器 (JSON Extractor)</strong></td><td>用 JsonPath 从 JSON 响应提取值</td></tr><tr><td><strong>正则表达式提取器 (Regular Expression Extractor)</strong></td><td>用正则从任意文本提取值</td></tr><tr><td><strong>边界提取器 (Boundary Extractor)</strong></td><td>用左右边界从文本提取值</td></tr><tr><td><strong>CSS/JQuery 提取器 (CSS/JQuery Extractor)</strong></td><td>用 CSS 选择器从 HTML 提取值</td></tr><tr><td><strong>XPath 提取器 (XPath Extractor)</strong></td><td>用 XPath 从 XML 提取值</td></tr><tr><td><strong>JSON JMESPath 提取器 (JSON JMESPath Extractor)</strong></td><td>用 JMESPath 语法提取 JSON</td></tr><tr><td><strong>JSR223 后置处理程序 (JSR223 PostProcessor)</strong></td><td>Groovy 脚本自定义后置逻辑</td></tr><tr><td><strong>BeanShell 后置处理程序 (BeanShell PostProcessor)</strong></td><td>脚本自定义后置逻辑（已过时）</td></tr><tr><td><strong>调试后置处理程序 (Debug PostProcessor)</strong></td><td>输出当前变量和属性的值</td></tr><tr><td><strong>结果状态操作处理器 (Result Status Action Handler)</strong></td><td>根据条件改变取样器结果状态</td></tr></tbody></table><h2 id="断言-—-assertion" tabindex="-1">断言 — Assertion <a class="header-anchor" href="#断言-—-assertion" aria-label="Permalink to &quot;断言 — Assertion&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>响应断言 (Response Assertion)</strong></td><td>检查状态码或响应内容是否匹配</td></tr><tr><td><strong>持续时间断言 (Duration Assertion)</strong></td><td>响应超过指定时间就标失败</td></tr><tr><td><strong>大小断言 (Size Assertion)</strong></td><td>检查响应体大小</td></tr><tr><td><strong>JSON 断言 (JSON Assertion)</strong></td><td>用 JsonPath 校验 JSON 内容</td></tr><tr><td><strong>XPath 断言 (XPath Assertion)</strong></td><td>校验 XML 内容</td></tr><tr><td><strong>XML 断言 (XML Assertion)</strong></td><td>检查响应是否为合法的 XML</td></tr><tr><td><strong>XML Schema 断言 (XML Schema Assertion)</strong></td><td>用 XSD 校验 XML</td></tr><tr><td><strong>HTML 断言 (HTML Assertion)</strong></td><td>用 JTidy 校验 HTML 语法</td></tr><tr><td><strong>MD5Hex 断言 (MD5Hex Assertion)</strong></td><td>校验响应 MD5 哈希</td></tr><tr><td><strong>Compare 断言 (Compare Assertion)</strong></td><td>对比两个取样器的结果</td></tr><tr><td><strong>SMIME 断言 (SMIME Assertion)</strong></td><td>校验签名邮件</td></tr><tr><td><strong>BeanShell 断言 (BeanShell Assertion)</strong></td><td>脚本自定义断言（已过时）</td></tr><tr><td><strong>JSR223 断言 (JSR223 Assertion)</strong></td><td>Groovy 脚本自定义断言，推荐</td></tr></tbody></table><h2 id="监听器-—-listener" tabindex="-1">监听器 — Listener <a class="header-anchor" href="#监听器-—-listener" aria-label="Permalink to &quot;监听器 — Listener&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>察看结果树 (View Results Tree)</strong></td><td>逐个看请求/响应详情，调试用</td></tr><tr><td><strong>汇总报告 (Summary Report)</strong></td><td>平均、最快、最慢、错误率、吞吐量</td></tr><tr><td><strong>聚合报告 (Aggregate Report)</strong></td><td>汇总报告 + 中位数、P90/P95/P99</td></tr><tr><td><strong>用表格察看结果 (View Results in Table)</strong></td><td>表格形式看每次请求</td></tr><tr><td><strong>图形结果 (Graph Results)</strong></td><td>折线图</td></tr><tr><td><strong>响应时间图 (Response Time Graph)</strong></td><td>响应时间变化曲线</td></tr><tr><td><strong>断言结果 (Assertion Results)</strong></td><td>只看断言失败的信息</td></tr><tr><td><strong>邮件观察仪 (Mailer Visualizer)</strong></td><td>压测完成后发邮件通知</td></tr><tr><td><strong>保存响应到文件 (Save Responses to a file)</strong></td><td>把响应体存到文件</td></tr><tr><td><strong>简单数据写入器 (Simple Data Writer)</strong></td><td>把结果写到 JTL 文件</td></tr><tr><td><strong>后端监听器 (Backend Listener)</strong></td><td>实时推送到 InfluxDB / Graphite</td></tr><tr><td><strong>生成概要结果 (Generate Summary Results)</strong></td><td>日志中周期性输出统计摘要</td></tr></tbody></table><h2 id="常用内置函数" tabindex="-1">常用内置函数 <a class="header-anchor" href="#常用内置函数" aria-label="Permalink to &quot;常用内置函数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>${__time(format)}</code></td><td>当前时间戳，如 <code>${__time(yyyyMMddHHmmss)}</code></td></tr><tr><td><code>${__UUID()}</code></td><td>生成 UUID</td></tr><tr><td><code>${__Random(min, max)}</code></td><td>生成随机数</td></tr><tr><td><code>${__counter(TRUE/FALSE)}</code></td><td>自增计数器</td></tr><tr><td><code>${__threadNum()}</code></td><td>当前线程编号</td></tr><tr><td><code>${__P(propName)}</code></td><td>读取 JMeter 属性</td></tr><tr><td><code>${__CSVRead(file, col)}</code></td><td>逐行读 CSV 文件</td></tr><tr><td><code>${__jexl3(expr)}</code></td><td>JEXL3 条件表达式</td></tr><tr><td><code>${__groovy(expr)}</code></td><td>Groovy 表达式</td></tr><tr><td><code>${__V(varName)}</code></td><td>执行嵌套变量引用</td></tr></tbody></table><h2 id="非界面功能" tabindex="-1">非界面功能 <a class="header-anchor" href="#非界面功能" aria-label="Permalink to &quot;非界面功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>CLI 模式</strong></td><td><code>jmeter -n -t -l -e -o</code> 命令行压测</td></tr><tr><td><strong>HTML 报告</strong></td><td>Dashboard + Charts + 自定义图表</td></tr><tr><td><strong>分布式压测</strong></td><td>Controller + 多 Agent 协同施压</td></tr><tr><td><strong>Plugins Manager</strong></td><td>插件管理，200+ 插件</td></tr><tr><td><strong>HTTP(S) Test Script Recorder</strong></td><td>代理录制浏览器操作生成脚本</td></tr></tbody></table><hr><blockquote><p>日常高频元件约 20 个：线程组、HTTP 请求、HTTP 请求默认值、HTTP 信息头管理器、CSV 数据文件设置、JSON 提取器、正则表达式提取器、响应断言、持续时间断言、均匀随机定时器、同步定时器、事务控制器、If 控制器、察看结果树、汇总报告、聚合报告、后端监听器。其余用到再查。</p></blockquote>',30)])])}const u=r(n,[["render",s]]);export{b as __pageData,u as default};
